package cn.mop.persistence;
import cn.mop.domain.DomainException;
import cn.mop.domain.change.*;
import cn.mop.domain.change.ChangeNoticeDraftRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import javax.sql.DataSource;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
/** Existing real PG; owned synthetic notices are retained and archived, never executed. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresChangeNoticeDraftIntegrationTest {
    static final String A="55000000-0000-4000-8000-000000000001",B="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresChangeNoticeDraftRepository repo;static String admin,asset,other,foreign;
    final List<String> owned=new ArrayList<>();
    @BeforeAll static void connect()throws Exception{String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);repo=new PostgresChangeNoticeDraftRepository(pool,platform);admin=actor("padmin");asset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+B+"' ORDER BY id LIMIT 1");other=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+B+"' ORDER BY id OFFSET 1 LIMIT 1");foreign=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+A+"' ORDER BY id LIMIT 1");assertEquals(List.of(),repo.readinessProblems());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    @AfterEach void archiveOwned(){for(String id:owned){var s=repo.get(access(),id);if(!s.archived())archive(s);}}
    static String scalar(String sql)throws SQLException{try(var c=pool.getConnection();var s=c.createStatement();var r=s.executeQuery(sql)){assertTrue(r.next());return r.getString(1);}}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),A).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(){return access(admin,B);}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static ChangeNoticeDraft draft(String name){return new ChangeNoticeDraft(UUID.fromString(B),UUID.fromString(admin),null,name,Instant.parse("2026-10-05T16:00:00.123Z"),null,List.of(UUID.fromString(other),UUID.fromString(asset)));}
    static String hash(Object v){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(v)));}catch(Exception e){throw new IllegalStateException(e);}}
    static Object command(Access a,String id,String route,String key,String hash,Supplier<Object> work){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->repo.authorizeCurrentAccess(a,id),work);}
    static Snapshot snapshot(Object v){return mapper.convertValue(v,Snapshot.class);}
    Snapshot create(String name){var a=access();var d=draft(name);var v=snapshot(command(a,null,"POST /integration/change-notice-drafts",UUID.randomUUID().toString(),hash(d),()->repo.create(a,d)));owned.add(v.id());return v;}
    Snapshot update(Snapshot before,ChangeNoticeDraft d){var a=access();return snapshot(command(a,before.id(),"PATCH /integration/change-notice-drafts/"+before.id(),UUID.randomUUID().toString(),hash(List.of(before.version(),d)),()->repo.update(a,before.id(),before.version(),d)));}
    Snapshot archive(Snapshot before){var a=access();return snapshot(command(a,before.id(),"POST /integration/change-notice-drafts/"+before.id()+"/archive",UUID.randomUUID().toString(),hash(before.version()),()->repo.archive(a,before.id(),before.version())));}
    Snapshot restore(Snapshot before){var a=access();return snapshot(command(a,before.id(),"POST /integration/change-notice-drafts/"+before.id()+"/restore",UUID.randomUUID().toString(),hash(before.version()),()->repo.restore(a,before.id(),before.version())));}
    static List<String> counts()throws SQLException{List<String> v=new ArrayList<>();for(String table:List.of("mop_change_notice_draft","mop_change_notice_revision","mop_change_notice_asset","mop_audit","mop_idempotency"))v.add(scalar("SELECT count(*)::text FROM public."+table));return v;}
    @Test void realCreateRoundTripKeepsUnverifiedIntentOrderedTargetsAndNoActivation(){var s=create("SYNTHETIC_NOTICE_REPO_CREATE");assertEquals(1,s.version());assertEquals(draft(s.draft().changeSummary()),s.draft());assertEquals(s,repo.get(access(),s.id()));assertFalse(s.draft().effective());assertNull(s.draft().approvalStatus());assertNull(s.draft().automaticP3Decision());assertFalse(s.draft().alertSuppressionAllowed());}
    @Test void updateAndHistoryRetainOriginalBytesAndActor(){var s=create("SYNTHETIC_NOTICE_REPO_HISTORY");var d=new ChangeNoticeDraft(UUID.fromString(B),UUID.fromString(admin),null,"SYNTHETIC_NOTICE_REPO_CHANGED \n😀",Instant.parse("2026-10-05T16:00:00.123Z"),Instant.parse("2026-10-06T01:02:03Z"),List.of(UUID.fromString(asset)));var newer=update(s,d);assertEquals(2,newer.version());var h=repo.history(access(),s.id(),10,null);assertEquals(List.of(2L,1L),h.stream().map(Revision::version).toList());assertEquals(s.draft(),h.get(1).draft());assertEquals(d,h.get(0).draft());assertEquals(admin,h.get(0).recordedBy());assertEquals(admin,newer.draft().applicantId().toString());assertFalse(newer.draft().deviceExecutionAllowed());}
    @Test void archiveRestorePreserveDefinitionAndStayDisabled(){var s=create("SYNTHETIC_NOTICE_REPO_LIFECYCLE");var archived=archive(s);assertTrue(archived.archived());assertEquals(s.draft(),archived.draft());assertEquals(409,assertThrows(DomainException.class,()->update(archived,draft("blocked"))).status);var restored=restore(archived);assertFalse(restored.archived());assertEquals(s.draft(),restored.draft());assertFalse(restored.draft().effective());assertEquals(409,assertThrows(DomainException.class,()->restore(restored)).status);}
    @Test void staleExpectedVersionCannotOverwriteHistory()throws Exception{var s=create("SYNTHETIC_NOTICE_REPO_CAS");update(s,draft("SYNTHETIC_NOTICE_REPO_CAS2"));var before=counts();assertEquals(409,assertThrows(DomainException.class,()->update(s,draft("stale"))).status);assertEquals(before,counts());}
    @Test void sameKeyReplaysOriginalReceiptWithoutAnotherRevision()throws Exception{var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_REPLAY");String key=UUID.randomUUID().toString(),route="POST /integration/notice-replay";var one=snapshot(command(a,null,route,key,hash(d),()->repo.create(a,d)));owned.add(one.id());var before=counts();var two=snapshot(command(a,null,route,key,hash(d),()->{throw new AssertionError("must not reexecute");}));assertEquals(one,two);assertEquals(before,counts());}
    @Test void originalReplayAfterArchiveKeepsOriginalUnarchivedReceipt(){var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_OLD_RECEIPT");String key=UUID.randomUUID().toString(),route="POST /integration/notice-old";var one=snapshot(command(a,null,route,key,hash(d),()->repo.create(a,d)));owned.add(one.id());archive(one);assertEquals(one,snapshot(command(a,null,route,key,hash(d),()->{throw new AssertionError();})));assertTrue(repo.get(a,one.id()).archived());}
    @Test void changedBodySameKeyIsConflictBeforeMutation()throws Exception{var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_KEY");String key=UUID.randomUUID().toString(),route="POST /integration/notice-key";owned.add(snapshot(command(a,null,route,key,hash(d),()->repo.create(a,d))).id());var before=counts();assertEquals(409,assertThrows(DomainException.class,()->command(a,null,route,key,hash(draft("changed")),()->repo.create(a,d))).status);assertEquals(before,counts());}
    @Test void successfulReadonlyQueriesDoNotAppendAuditOrReceipt()throws Exception{var s=create("SYNTHETIC_NOTICE_REPO_READ");var before=counts();repo.get(access(),s.id());repo.list(access(),10,null,null);repo.history(access(),s.id(),10,null);assertEquals(before,counts());}
    @Test void currentMembershipAndPermissionVersionAreRequired(){var s=create("SYNTHETIC_NOTICE_REPO_AUTH");var a=access();assertEquals(401,assertThrows(DomainException.class,()->repo.get(new Access(a.actorId(),B,a.permissionVersion()+1,a.traceId()),s.id())).status);var viewer=access(actor("viewer"),A);assertEquals(403,assertThrows(DomainException.class,()->repo.list(viewer,10,null,null)).status);assertEquals(403,assertThrows(DomainException.class,()->repo.history(viewer,s.id(),10,null)).status);}
    @Test void crossTenantPlansAndTargetsReturn404()throws Exception{var s=create("SYNTHETIC_NOTICE_REPO_SCOPE");assertEquals(404,assertThrows(DomainException.class,()->repo.get(access(admin,A),s.id())).status);assertEquals(404,assertThrows(DomainException.class,()->repo.history(access(admin,A),s.id(),10,null)).status);var a=access();var bad=new ChangeNoticeDraft(UUID.fromString(B),UUID.fromString(admin),null,"SYNTHETIC_CROSS",Instant.parse("2026-10-05T00:00:00Z"),null,List.of(UUID.fromString(foreign)));var before=counts();assertEquals(404,assertThrows(DomainException.class,()->command(a,null,"POST /integration/notice-scope",UUID.randomUUID().toString(),hash(bad),()->repo.create(a,bad))).status);assertEquals(before,counts());}
    @Test void missingTargetsOrMismatchedDraftTenantDoNotCreateHead()throws Exception{for(var d:List.of(new ChangeNoticeDraft(UUID.fromString(B),UUID.fromString(admin),null,"SYNTHETIC",Instant.parse("2026-10-05T00:00:00Z"),null,List.of(UUID.randomUUID())),new ChangeNoticeDraft(UUID.fromString(A),UUID.fromString(admin),null,"SYNTHETIC",Instant.parse("2026-10-05T00:00:00Z"),null,List.of(UUID.fromString(asset))))){var a=access();var before=counts();assertEquals(404,assertThrows(DomainException.class,()->command(a,null,"POST /integration/notice-missing",UUID.randomUUID().toString(),hash(d),()->repo.create(a,d))).status);assertEquals(before,counts());}}
    @Test void callerFailureRollsBackAllFiveTables()throws Exception{var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_ROLLBACK");var before=counts();assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/notice-rollback",UUID.randomUUID().toString(),hash(d),()->{repo.create(a,d);throw new IllegalStateException("Synthetic caller failure");}));assertEquals(before,counts());}
    @Test void unprotectedWritesAndIndependentReadInsideCommandAreRejected()throws Exception{var a=access();var before=counts();assertThrows(IllegalStateException.class,()->repo.create(a,draft("SYNTHETIC")));assertThrows(IllegalStateException.class,()->repo.authorizeCurrentAccess(a,null));assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/notice-nested",UUID.randomUUID().toString(),"a".repeat(64),()->repo.list(a,10,null,null)));assertEquals(before,counts());}
    @Test void authorizationCallbackPrecedesCachedReceipt(){var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_CALLBACK");String key=UUID.randomUUID().toString(),route="POST /integration/notice-callback";owned.add(snapshot(command(a,null,route,key,hash(d),()->repo.create(a,d))).id());assertEquals(403,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),B,route,key,hash(d),a.permissionVersion(),()->{throw new DomainException(403,"ACTION_FORBIDDEN","Synthetic callback rejection");},()->null)).status);}
    @Test void stableBoundedPagesAndHistoryCursorDoNotDuplicate(){for(int i=0;i<3;i++)create("SYNTHETIC_NOTICE_REPO_PAGE"+i);var page=repo.list(access(),2,null,null);assertEquals(2,page.size());var tail=page.get(1);var next=repo.list(access(),2,tail.createdAt(),tail.id());var ids=new HashSet<String>();for(var s:page)assertTrue(ids.add(s.id()));for(var s:next)assertTrue(ids.add(s.id()));var one=repo.get(access(),owned.get(0));update(one,draft("SYNTHETIC_NOTICE_REPO_NEXT"));assertEquals(List.of(1L),repo.history(access(),one.id(),10,2L).stream().map(Revision::version).toList());}
    @Test void invalidPaginationAndVersionFailBeforeMutation(){var a=access();for(int n:List.of(0,102))assertEquals(400,assertThrows(DomainException.class,()->repo.list(a,n,null,null)).status);assertThrows(DomainException.class,()->repo.list(a,10,Instant.now(),null));assertThrows(DomainException.class,()->repo.history(a,UUID.randomUUID().toString(),10,0L));var s=create("SYNTHETIC_NOTICE_REPO_BAD_VERSION");assertEquals(400,assertThrows(DomainException.class,()->command(a,s.id(),"PATCH /integration/notice-invalid",UUID.randomUUID().toString(),"a".repeat(64),()->repo.update(a,s.id(),0,draft("invalid")))).status);}
    @Test void concurrentOriginalKeyProducesOneCommitAndOneAudit()throws Exception{var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_CONCURRENT");String key=UUID.randomUUID().toString(),route="POST /integration/notice-concurrent";var gate=new CountDownLatch(1);var executor=Executors.newFixedThreadPool(2);try{Callable<Snapshot> work=()->{gate.await();return snapshot(command(a,null,route,key,hash(d),()->repo.create(a,d)));};var f1=executor.submit(work);var f2=executor.submit(work);gate.countDown();var s1=f1.get(15,TimeUnit.SECONDS);var s2=f2.get(15,TimeUnit.SECONDS);owned.add(s1.id());assertEquals(s1,s2);assertEquals("1",scalar("SELECT count(*)::text FROM public.mop_audit WHERE payload->>'resource_id'='"+s1.id()+"' AND payload->>'action'='change_notice.draft.create'"));}finally{executor.shutdownNow();}}
    @Test void concurrentDifferentKeysWithSameExpectedVersionHaveOneWinner()throws Exception{
        var original=create("SYNTHETIC_NOTICE_REPO_CONCURRENT_CAS");var gate=new CountDownLatch(1);var executor=Executors.newFixedThreadPool(2);
        try{Callable<Integer> work=()->{gate.await();try{update(original,draft("SYNTHETIC_NOTICE_REPO_CAS_WINNER"));return 200;}catch(DomainException e){return e.status;}};
            var f1=executor.submit(work);var f2=executor.submit(work);gate.countDown();var codes=new ArrayList<>(List.of(f1.get(15,TimeUnit.SECONDS),f2.get(15,TimeUnit.SECONDS)));Collections.sort(codes);assertEquals(List.of(200,409),codes);assertEquals(2,repo.get(access(),original.id()).version());assertEquals(2,repo.history(access(),original.id(),10,null).size());
        }finally{executor.shutdownNow();}
    }
    @Test void corruptedSuppressionReadFailsClosedWithoutChangingRealDatabase()throws Exception{
        var original=create("SYNTHETIC_NOTICE_REPO_READ_CORRUPTION");var before=counts();
        DataSource altered=(DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{
            if(m.getName().equals("getConnection")){var c=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0]instanceof String sql&&sql.startsWith("SELECT h.id::text")){
                    var ps=(PreparedStatement)invoke(cm,c,ca);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{
                        if(sm.getName().equals("executeQuery")){var rows=(ResultSet)invoke(sm,ps,sa);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{ResultSet.class},(rp,rm,ra)->{if(rm.getName().equals("getBoolean")&&"alert_suppression_allowed".equals(ra[0]))return true;return invoke(rm,rows,ra);});}return invoke(sm,ps,sa);});}
                return invoke(cm,c,ca);});}return invoke(m,pool,a);});
        var reader=new PostgresChangeNoticeDraftRepository(altered,platform);assertEquals(503,assertThrows(DomainException.class,()->reader.get(access(),original.id())).status);assertEquals(before,counts());assertEquals(original,repo.get(access(),original.id()));
    }
    @Test void corruptedContentDigestReadFailsClosedWithoutChangingRealDatabase()throws Exception{
        var original=create("SYNTHETIC_NOTICE_REPO_HASH_CORRUPTION");var before=counts();
        DataSource altered=(DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,a)->{
            if(m.getName().equals("getConnection")){var c=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0]instanceof String sql&&sql.startsWith("SELECT h.id::text")){
                    var ps=(PreparedStatement)invoke(cm,c,ca);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{
                        if(sm.getName().equals("executeQuery")){var rows=(ResultSet)invoke(sm,ps,sa);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{ResultSet.class},(rp,rm,ra)->{if(rm.getName().equals("getString")&&"content_sha256".equals(ra[0]))return "0".repeat(64);return invoke(rm,rows,ra);});}return invoke(sm,ps,sa);});}
                return invoke(cm,c,ca);});}return invoke(m,pool,a);});
        var reader=new PostgresChangeNoticeDraftRepository(altered,platform);assertEquals(503,assertThrows(DomainException.class,()->reader.get(access(),original.id())).status);assertEquals(before,counts());assertEquals(original,repo.get(access(),original.id()));
    }
    static Object invoke(java.lang.reflect.Method method,Object target,Object[] args)throws Throwable{try{return method.invoke(target,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}}
    @Test void actualAuditSqlFailureRollsBackEverything()throws Exception{injectedWriteFailure(true);}
    @Test void actualTargetForeignKeyFailureRollsBackEverything()throws Exception{injectedWriteFailure(false);}
    void injectedWriteFailure(boolean audit)throws Exception{
        DataSource injected=(DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(p,m,args)->{
            if(m.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0]instanceof String sql){if(audit&&sql.startsWith("INSERT INTO public.mop_audit")){try(var statement=real.createStatement()){statement.execute("SELECT 1/0");}}
                    if(!audit&&sql.startsWith("INSERT INTO public.mop_change_notice_asset")){PreparedStatement statement=(PreparedStatement)cm.invoke(real,ca);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{if(sm.getName().equals("setString")&&Integer.valueOf(5).equals(sa[0]))sa=new Object[]{5,foreign};try{return sm.invoke(statement,sa);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}}
                try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}
            try{return m.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});
        var otherPlatform=new PostgresPlatformRepository(injected,mapper);var otherRepo=new PostgresChangeNoticeDraftRepository(injected,otherPlatform);var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_FAULT");var before=counts();assertEquals(503,assertThrows(DomainException.class,()->otherPlatform.idempotentAuthorized(a.actorId(),B,"POST /integration/notice-fault",UUID.randomUUID().toString(),hash(d),a.permissionVersion(),()->otherRepo.authorizeCurrentAccess(a,null),()->otherRepo.create(a,d))).status);assertEquals(before,counts());
    }
    @Test void applicantMustBeCurrentActorOnCreateAndCannotBeReboundOnUpdate()throws Exception{var d=draft("SYNTHETIC_NOTICE_REPO_APPLICANT");var forged=new ChangeNoticeDraft(d.tenantId(),UUID.fromString(actor("viewer")),null,d.changeSummary(),d.plannedStartAt(),null,d.assetIds());var a=access();var before=counts();assertEquals(400,assertThrows(DomainException.class,()->command(a,null,"POST /integration/notice-applicant",UUID.randomUUID().toString(),hash(forged),()->repo.create(a,forged))).status);assertEquals(before,counts());var original=create(d.changeSummary());var current=counts();assertEquals(400,assertThrows(DomainException.class,()->update(original,forged)).status);assertEquals(current,counts());assertEquals(admin,repo.get(a,original.id()).draft().applicantId().toString());}
    @Test void optionalTicketRequiresActualSameTenantObject()throws Exception{String ticket=scalar("SELECT id::text FROM public.mop_ticket WHERE tenant_id='"+B+"' ORDER BY id LIMIT 1"),foreignTicket=scalar("SELECT id::text FROM public.mop_ticket WHERE tenant_id='"+A+"' ORDER BY id LIMIT 1");var a=access();var d=draft("SYNTHETIC_NOTICE_REPO_TICKET");for(String ref:List.of(foreignTicket,UUID.randomUUID().toString())){var bad=new ChangeNoticeDraft(d.tenantId(),d.applicantId(),UUID.fromString(ref),d.changeSummary(),d.plannedStartAt(),null,d.assetIds());var before=counts();assertEquals(404,assertThrows(DomainException.class,()->command(a,null,"POST /integration/notice-ticket",UUID.randomUUID().toString(),hash(bad),()->repo.create(a,bad))).status);assertEquals(before,counts());}var good=new ChangeNoticeDraft(d.tenantId(),d.applicantId(),UUID.fromString(ticket),d.changeSummary(),d.plannedStartAt(),null,d.assetIds());var created=snapshot(command(a,null,"POST /integration/notice-ticket",UUID.randomUUID().toString(),hash(good),()->repo.create(a,good)));owned.add(created.id());assertEquals(good,repo.get(a,created.id()).draft());assertEquals(UUID.fromString(ticket),repo.history(a,created.id(),10,null).get(0).draft().ticketId());}

}
